                        //                "canWd": true,
                        //                "ccy": "USDT",
                        //                "chain": "USDT-ERC20",
                        //                "logoLink":
                        //                "https://static.coinall.ltd/cdn/assets/imgs/221/5F74EB20302D7761.png",
                        //                "mainNet": false,
                        //                "maxFee": "16",
                        //                "maxWd": "8852150",
